This fix may be combined with another one in the ethtool subsystem:
https://lore.kernel.org/all/20260322075917.254874-1-alex.popov@linux.com/T/#u

Fixes: d43c65b05b848e0b ("ethtool: runtime-resume netdev parent in ethnl_ops_begin")
Cc: stable@vger.kernel.org
Signed-off-by: Alexander Popov <alex.popov@linux.com>
Acked-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Reviewed-by: Breno Leitao <leitao@debian.org>
Link: https://patch.msgid.link/20260324224607.374327-1-alex.popov@linux.com
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The bug is a use-after-free caused by setting the parent device of the virt_wifi net device to the lower device via `SET_NETDEV_DEV(dev, &priv->lowerdev->dev)`. When the virt_wifi device is unregistered, the lower device may be freed before the virtual device's cleanup completes, leaving the `dev->parent` pointer dangling. Subsequent ethtool operations (e.g., `ethnl_set_features`) call `pm_runtime_get_sync(dev->dev.parent)` through `ethnl_ops_begin()`, which then accesses the freed memory, resulting in the KASAN use-after-free report.

Here is the patch:
 /* Called with rtnl lock held. */
 static int virt_wifi_newlink(struct net_device *dev,
 			     struct rtnl_newlink_params *params,
 			     struct netlink_ext_ack *extack)
 {
 	struct virt_wifi_netdev_priv *priv = netdev_priv(dev);
 	struct net *link_net = rtnl_newlink_link_net(params);
 	struct nlattr **tb = params->tb;
 	int err;

 	if (!tb[IFLA_LINK])
 		return -EINVAL;

 	netif_carrier_off(dev);

 	priv->upperdev = dev;
 	priv->lowerdev = __dev_get_by_index(link_net,
 					    nla_get_u32(tb[IFLA_LINK]));

 	if (!priv->lowerdev)
 		return -ENODEV;
 	if (!tb[IFLA_MTU])
 		dev->mtu = priv->lowerdev->mtu;
 	else if (dev->mtu > priv->lowerdev->mtu)
 		return -EINVAL;

 	err = netdev_rx_handler_register(priv->lowerdev, virt_wifi_rx_handler,
 					 priv);
 	if (err) {
 		dev_err(&priv->lowerdev->dev,
 			"can't netdev_rx_handler_register: %d\n", err);
 		return err;
 	}

 	eth_hw_addr_inherit(dev, priv->lowerdev);
 	netif_stacked_transfer_operstate(priv->lowerdev, dev);

-	SET_NETDEV_DEV(dev, &priv->lowerdev->dev);
 	dev->ieee80211_ptr = kzalloc_obj(*dev->ieee80211_ptr);

 	if (!dev->ieee80211_ptr) {
 		err = -ENOMEM;
 		goto remove_handler;
 	}

 	dev->ieee80211_ptr->iftype = NL80211_IFTYPE_STATION;
 	dev->ieee80211_ptr->wiphy = common_wiphy;

 	err = register_netdevice(dev);
 	if (err) {
 		dev_err(&priv->lowerdev->dev, "can't register_netdevice: %d\n",
 			err);
 		goto free_wireless_dev;
 	}

 	err = netdev_upper_dev_link(priv->lowerdev, dev, extack);
 	if (err) {
 		dev_err(&priv->lowerdev->dev, "can't netdev_upper_dev_link: %d\n",
 			err);
 		goto unregister_netdev;
 	}

 	dev->priv_destructor = virt_wifi_net_device_destructor;
 	priv->being_deleted = false;
 	priv->is_connected = false;
 	priv->is_up = false;
 	INIT_DELAYED_WORK(&priv->connect, virt_wifi_connect_complete);
 	__module_get(THIS_MODULE);

 	return 0;
 unregister_netdev:
 	unregister_netdevice(dev);
 free_wireless_dev:
 	kfree(dev->ieee80211_ptr);
 	dev->ieee80211_ptr = NULL;
 remove_handler:
 	netdev_rx_handler_unregister(priv->lowerdev);

 	return err;
 }



